import{_ as t,o as s,c as a,a5 as o}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"Wheel Control — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/wheel.md","filePath":"software/sdk/cpp/wheel.md","lastUpdated":1793350928000}'),n={name:"software/sdk/cpp/wheel.md"};function i(r,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="wheel-control-—-c-example" tabindex="-1">Wheel Control — C++ Example <a class="header-anchor" href="#wheel-control-—-c-example" aria-label="Permalink to &quot;Wheel Control — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq/rbq_wheel.cpp</code></p><p>Spins the four wheels of an <strong>RBQ wheel robot (RBQ-W)</strong> from an external app. It takes ownership of the wheel joints only, so the legs stay with the robot&#39;s own controller and it keeps standing. It drives the wheels for a few seconds, then releases them.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>torque kd seconds</code> from the command line.</li><li>Initializes the DDS <code>ChannelFactory</code> on the given interface and creates, for <strong>app slot 21</strong>, a <code>Publisher&lt;MotionRef_&gt;</code> on <code>rt/rbq/ref/motion/_21</code> and a <code>Publisher&lt;JointOwnershipCmd_&gt;</code> on <code>rt/rbq/cmd/motion/owner/_21</code>. It also subscribes to <code>rt/rbq/ref/motion/_0</code>, the reference the robot actually applies.</li><li>Waits ~500 ms for DDS discovery, publishes a first zero-torque reference, then sends <code>JointOwnershipCmd_</code> with <code>whl_joint[] = true</code> (<code>leg_joint[]</code> stays <code>false</code>).</li><li>Publishes <code>whl_joint[]</code> at 500 Hz with <code>kp = 0</code>, the given <code>kd</code> and a torque ramped from 0 over 0.5 s. Every 0.5 s it prints the applied wheel reference.</li><li>When time is up it sets the torque to 0 for 0.5 s, then publishes <code>kp = kd = torque = 0</code> and exits.</li></ol><p>With <code>kp = 0</code> the wheel board applies <code>torque − kd × velocity</code>, so a free wheel settles at <strong>velocity = torque / kd</strong> [rad/s]. The defaults give 2 rad/s.</p><p>Gains are sent as <strong>physical values</strong> (Nm/rad, Nm·s/rad) on both CAN FD and classic CAN robots. The on-robot <strong>Network</strong> converts them for the board, so classic CAN robots round them to the board&#39;s gain step (e.g. kd 0.5 → 0.5007).</p><p><code>rbq_low_level</code> uses app slot 20, so the two examples can run together: legs from one app, wheels from the other.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>On the ground the robot <strong>rolls</strong> while the wheels turn. Give it room, start with a small torque, and keep the remote E-Stop at hand.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>The robot stack running and reachable on the same DDS interface.</li><li><strong>An RBQ wheel robot (RBQ-W)</strong>, standing. On a robot without wheels the command has no effect. In the simulator start Motion and MuJoCo with <code>--wheel</code> (<code>bash scripts/sim.bash --robot wheel</code>).</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_wheel</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run {#run}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [interface] [torque] [kd] [seconds]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2 rad/s forward for 3 s (the defaults) — the interface always comes first:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Backward, 1 rad/s, for 5 s:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>All arguments are positional, so <strong>the interface must be the first argument</strong>. Use the interface that reaches the robot — <code>lo</code> when running on the robot PC, your NIC from another host.</p><table tabindex="0"><thead><tr><th>Arg</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS interface (<code>lo</code> on the robot / NIC from another host)</td><td>—</td></tr><tr><td><code>torque</code></td><td>feed-forward wheel torque [Nm], |torque| ≤ 10</td><td><code>1.0</code></td></tr><tr><td><code>kd</code></td><td>wheel damping [Nm·s/rad], 0 &lt; kd ≤ 6</td><td><code>0.5</code></td></tr><tr><td><code>seconds</code></td><td>how long to drive before releasing the wheels</td><td><code>3</code></td></tr></tbody></table><p>Out-of-range values print the usage and exit without sending anything.</p><p>After the example exits, the wheels stay with app 21 at zero gains, so they turn freely. Standing up again or changing gait does not give them back to the robot. Restart the robot stack when the robot&#39;s own controller needs the wheels again.</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_wheel] wheel ownership requested (app 21)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0 kd=3.5) HLW(tq=0 kd=3.5) FRW(tq=0 kd=3.5) FLW(tq=0 kd=3.5)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0.996 kd=0.5) HLW(tq=0.996 kd=0.5) FRW(tq=0.996 kd=0.5) FLW(tq=0.996 kd=0.5)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=1 kd=0.5) HLW(tq=1 kd=0.5) FRW(tq=1 kd=0.5) FLW(tq=1 kd=0.5)</span></span>
<span class="line"><span>[rbq_wheel] done - wheels released (kp = kd = torque = 0)</span></span></code></pre></div><p>The first line shows the robot&#39;s own wheel gains before the hand-over. Wheel order is <code>HRW HLW FRW FLW</code> (joints 12–15).</p>`,24)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
